const body = ($input.item.json && $input.item.json.body) || $input.item.json || {};
const secret = body.internal_secret || '';
const expected = $env.INTERNAL_EMAIL_SECRET || '';
if (!expected || secret !== expected) return { json: { _unauthorized: true, error: 'internal secret required' } };
if (!body.decision_id || !body.action_type) return { json: { _empty: true, error: 'decision_id and action_type required' } };
return { json: {
  _authorized: true,
  decision_id: body.decision_id,
  action_type: body.action_type,
  channel: body.channel || null,
  message: body.message || '',
  lead_id: body.lead_id,
  client_id: body.client_id,
  trigger_id: body.trigger_id || null
} };

const ins = $input.item.json;
const row = Array.isArray(ins) ? ins[0] : ins;
const ctx = $('Validate').item.json;
return { json: Object.assign({}, ctx, { agent_action_id: (row && row.id) || null }) };

// Fail-closed policy gate. Nothing sensitive executes unless this says so.
//
// Before this node existed the executor validated a shared secret, wrote an
// agent_actions row, and routed straight to WhatsApp/SMS/Email/Voice. Autonomy
// level, risk class and approval state were never consulted -- the fields were
// carried in agent_personalities and read by nothing.
//
// Order matters: every DENY path is evaluated before any ALLOW, so a missing,
// malformed or unrecognised input can only ever result in a block.

var ctx = $('Carry Action ID').item.json;
var polResp = $input.item.json;

// The policy fetch uses neverError + alwaysOutputData, so an empty result is
// an object or an empty array rather than a halted branch.
var rows = Array.isArray(polResp) ? polResp : (polResp && polResp.id ? [polResp] : []);
var policy = rows.length ? rows[0] : null;

var correlation_id = ctx.agent_action_id || ctx.decision_id || null;

function deny(reason, detail, risk, autonomy) {
  return { json: Object.assign({}, ctx, {
    _allowed: false,
    _status: (reason === 'approval_required') ? 'approval_required' : 'denied',
    policy_result: {
      allowed: false,
      reason: reason,
      detail: detail,
      risk_class: risk || 'UNKNOWN',
      autonomy_level: autonomy || null,
      approval_required: true,
      approval_state: 'missing',
      correlation_id: correlation_id,
      evaluated_at: new Date().toISOString()
    }
  }) };
}

// --- risk classification -------------------------------------------------
// Keyed on capability, not product, so a new product inherits the policy
// instead of needing a new branch.
// --- one canonical action vocabulary -------------------------------------
// Three vocabularies were in play and no send could ever complete, which
// hid the problem behind a pair of accidental refusals:
//
//   decision engine emits  send_email / phone_call / ...
//   MCP hands over         email / voice / book
//   Switch Action Type routes on  send_email / phone_call / book
//   this registry keyed on        email / voice / book
//
// So an agent decision (send_email) missed the registry and was denied as
// UNKNOWN -- fail-closed, but never a policy decision. An MCP handover
// (email) classified correctly and then matched no Switch route. Both
// halves refused for the wrong reason.
//
// Everything normalises here, once, to the vocabulary the Switch already
// routes on. This is the only risk registry; MCP classifies capabilities
// for authorisation, this classifies actions for execution, and neither
// duplicates the other.
var ALIAS = {
  email: 'send_email',
  sms: 'send_sms',
  whatsapp: 'send_whatsapp',
  voice: 'phone_call',
  call: 'phone_call',
  place_outbound_call: 'phone_call',
  video: 'send_video',
  book: 'book_meeting',
  outreach_send: 'send_email',
  email_send: 'send_email'
};

var RISK = {
  send_email: 'CONTACT_HUMAN',
  send_sms: 'CONTACT_HUMAN',
  send_whatsapp: 'CONTACT_HUMAN',
  phone_call: 'CONTACT_HUMAN',
  publish_social: 'CONTACT_HUMAN',
  // Booking reaches a real person's calendar, so it sits with the other
  // contact-a-human capabilities rather than with internal writes.
  book_meeting: 'CONTACT_HUMAN',
  charge_payment: 'FINANCIAL',
  capture_payment: 'FINANCIAL',
  refund_payment: 'FINANCIAL',
  finalize_auction: 'FINANCIAL',
  create_order: 'FINANCIAL',
  cancel_order: 'DESTRUCTIVE',
  adjust_inventory: 'DESTRUCTIVE',
  delete_record: 'DESTRUCTIVE',
  finalize_policy: 'REGULATED',
  submit_application: 'REGULATED',
  bind_coverage: 'REGULATED',
  send_video: 'WRITE_INTERNAL',
  draft_outreach: 'WRITE_INTERNAL',
  draft_quote: 'WRITE_INTERNAL',
  update_lead_status: 'WRITE_INTERNAL',
  log_decision: 'WRITE_INTERNAL',
  escalate: 'WRITE_INTERNAL',
  research_lead: 'READ',
  score_lead: 'READ',
  get_vertical_context: 'READ',
  get_pipeline_stats: 'READ',
  get_inventory: 'READ',
  check_system_health: 'READ',
  retrieve_lead_memory: 'READ',
  recommend: 'REASONING',
  plan: 'REASONING'
};

function normalise(v) {
  var s = String(v || '').toLowerCase();
  return ALIAS.hasOwnProperty(s) ? ALIAS[s] : s;
}

var rawAction = String(ctx.action_type || '').toLowerCase();
var action = normalise(rawAction);

// Downstream routing must see the same canonical value this gate judged.
// Switch Action Type reads $json.action_type, so normalising it here keeps
// classification and execution from ever disagreeing again.
ctx.action_type = action;
ctx.raw_action_type = rawAction;

// 1. Unknown capability -> deny. An unrecognised action_type has no risk
//    class, and guessing one is how an unreviewed capability slips through.
if (!action || !RISK.hasOwnProperty(action)) {
  return deny('unknown_action_type', 'no risk class registered for "' + action + '"', 'UNKNOWN', null);
}
var risk = RISK[action];

// 2. Missing policy metadata -> deny. No personality means no autonomy level,
//    and an unknown autonomy level must never mean "full autonomy".
if (!policy) {
  return deny('missing_policy', 'no agent_personalities row for this client', risk, null);
}

// 3. Tenant isolation. Approval is not authorization: an approved action still
//    may not cross a tenant boundary.
if (!ctx.client_id || !policy.client_id || String(policy.client_id) !== String(ctx.client_id)) {
  return deny('tenant_mismatch', 'policy tenant does not match requested tenant', risk, null);
}

var rules = policy.escalation_rules || {};
var autonomy = rules.autonomy_level || null;
if (!autonomy) {
  return deny('missing_autonomy_level', 'personality carries no autonomy_level', risk, null);
}

// 4. Explicit prohibition always wins, whatever the risk class.
var prohibited = policy.prohibited_topics || [];
if (Array.isArray(prohibited) && prohibited.indexOf(action) !== -1) {
  return deny('prohibited_action', 'action is in prohibited_topics', risk, autonomy);
}

// 5. Approval object, if one was supplied. Validated rather than trusted:
//    it must be complete, and must name this tenant and this action.
var appr = ctx.approval || (ctx.body && ctx.body.approval) || null;
var approvalValid = false;
if (appr && typeof appr === 'object') {
  approvalValid = Boolean(appr.approval_id) && Boolean(appr.approved_by) &&
                  Boolean(appr.approved_at) &&
                  String(appr.client_id || '') === String(ctx.client_id) &&
                  normalise(appr.action_type) === action;
}

// 6. Classes that always need a human, unless a valid approval accompanies
//    the request.
var NEEDS_APPROVAL = ['CONTACT_HUMAN', 'FINANCIAL', 'DESTRUCTIVE', 'REGULATED'];
if (NEEDS_APPROVAL.indexOf(risk) !== -1) {
  if (!approvalValid) {
    return deny('approval_required', risk + ' actions require human approval', risk, autonomy);
  }
}

// 7. Autonomy ceiling. recommend_only may reason and read and prepare
//    internal drafts, and may not reach anything on the sensitive list even
//    with an approval object attached -- the personality itself forbids it.
if (autonomy === 'recommend_only' && NEEDS_APPROVAL.indexOf(risk) !== -1) {
  return deny('autonomy_forbids', 'autonomy_level recommend_only cannot execute ' + risk, risk, autonomy);
}

// 8. Per-action gate declared on the personality.
var gated = rules.require_human_approval || [];
if (Array.isArray(gated) && gated.indexOf(action) !== -1 && !approvalValid) {
  return deny('approval_required', 'action listed in require_human_approval', risk, autonomy);
}

// 9. WRITE_INTERNAL needs the action to be explicitly permitted.
if (risk === 'WRITE_INTERNAL') {
  var allowed = rules.auto_allowed || [];
  if (!Array.isArray(allowed) || allowed.indexOf(action) === -1) {
    return deny('not_in_auto_allowed', 'WRITE_INTERNAL action not explicitly permitted', risk, autonomy);
  }
}

// Allowed. READ and REASONING reach here on any autonomy level; everything
// else has passed an explicit permit above.
return { json: Object.assign({}, ctx, {
  _allowed: true,
  _status: 'executing',
  policy_result: {
    allowed: true,
    reason: 'permitted',
    risk_class: risk,
    autonomy_level: autonomy,
    approval_required: NEEDS_APPROVAL.indexOf(risk) !== -1,
    approval_state: approvalValid ? 'valid' : 'not_required',
    correlation_id: correlation_id,
    evaluated_at: new Date().toISOString()
  }
}) };
